 {(view === 'Transactions' || view === 'Income') && <><div className="bc-section-head"><button className="bc-primary" onClick={() => open(view === 'Income' ? 'income' : 'expense')}>{view === 'Income' ? 'Add Income' : 'Add Transaction'}</button><span>{rows.length} matching records</span></div><button onClick={()=>{filterBefore.current=context;setFiltersOpen(true)}}>Search and filters{[search,accountId,filterType,filterStatus,filterCategory,filterGroup,minAmount,maxAmount,frequency,dateFrom,dateTo].filter(Boolean).length>0?' · Applied':''}</button><section className="bc-card">{txList(view === 'Income' ? rows.filter(t => t.type === 'income') : rows)}</section></>}
